import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type GradientTextProps = Record<string, any>;

const GradientText: React.FC<GradientTextProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "Gradient Text Animation",
  fontFamily = "Montserrat",
  gradientColorStart = "#FF0080",
  gradientColorEnd = "#7928CA",
  gradientAngle = 45,
  fontSize = 120,
  animationSpeed = 1.5,
}) => {
  
  {/* Load Google Fonts */ }
  useFontLoader([fontFamily]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Entrance Animation (Spring Scale + Fade)
  const entrance = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
    durationInFrames: 30,
  });

  const opacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Gradient Movement Animation
  // Moving the background position to create a shimmering effect
  const gradientPos = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [0, 100 * animationSpeed]
  );

  const textStyle: React.CSSProperties = {
    fontFamily: fontFamily,
    fontWeight: 900,
    fontSize: fontSize,
    textAlign: "center",
    lineHeight: 1.1,
    // Gradient Logic
    backgroundImage: `linear-gradient(${gradientAngle}deg, ${gradientColorStart}, ${gradientColorEnd}, ${gradientColorStart})`,
    backgroundSize: "300% 300%",
    backgroundPosition: `${gradientPos}% 50%`,
    backgroundClip: "text",
    WebkitBackgroundClip: "text",
    color: "transparent",
    // Entrance Transforms
    transform: `scale(${entrance})`,
    opacity: opacity,
    padding: "20px", // Prevent clipping of some font ascenders/descenders
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={textStyle}>
        {titleText}
      </div>
    </AbsoluteFill>
  );
};

